1	package com.loja.checkout.service;
2	
3	import com.loja.checkout.domain.CheckoutException;
4	import com.loja.checkout.domain.Cupom;
5	import com.loja.checkout.domain.Dinheiro;
6	import com.loja.checkout.domain.FormaPagamento;
7	import com.loja.checkout.domain.ItemPedido;
8	import com.loja.checkout.domain.ModalidadeEntrega;
9	import com.loja.checkout.domain.NivelClube;
10	import com.loja.checkout.domain.Regiao;
11	import com.loja.checkout.domain.Resumo;
12	import com.loja.checkout.web.ItemRequest;
13	import com.loja.checkout.web.ResumoRequest;
14	import java.math.BigDecimal;
15	import java.util.ArrayList;
16	import java.util.List;
17	import org.springframework.stereotype.Service;
18	
19	/**
20	 * Monta o resumo da compra. Concentra o que é igual em todo pedido: a ordem do
21	 * cálculo e a ordem das validações. O que varia de caso para caso é delegado a
22	 * cada família (entrega, cupom, nível, pagamento) e à região.
23	 */
24	@Service
25	public class CalculadoraResumo {
26	
27	    public Resumo calcular(ResumoRequest req) {
28	        List<ItemPedido> itens = validarItens(req.itens());
29	
30	        NivelClube nivel = NivelClube.resolver(req.nivelClube())
31	                .orElseThrow(() -> new CheckoutException("NIVEL_CLUBE_INVALIDO"));
32	        Regiao regiao = Regiao.resolver(req.regiao())
33	                .orElseThrow(() -> new CheckoutException("REGIAO_INVALIDA"));
34	        ModalidadeEntrega modalidade = ModalidadeEntrega.resolver(req.modalidadeEntrega())
35	                .orElseThrow(() -> new CheckoutException("MODALIDADE_INVALIDA"));
36	
37	        BigDecimal peso = somar(itens.stream().map(ItemPedido::totalPeso).toList());
38	        if (!modalidade.disponivel(peso)) {
39	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
40	        }
41	
42	        BigDecimal subtotal = Dinheiro.centavos(somar(itens.stream().map(ItemPedido::totalPreco).toList()));
43	        BigDecimal frete = nivel.aplicarFrete(modalidade.frete(peso));
44	        BigDecimal desconto = resolverDesconto(req.cupom(), new Cupom.Contexto(subtotal, frete, itens));
45	
46	        FormaPagamento forma = FormaPagamento.resolver(req.formaPagamento())
47	                .orElseThrow(() -> new CheckoutException("FORMA_PAGAMENTO_INVALIDA"));
48	        int parcelas = req.parcelas() == null ? 1 : req.parcelas();
49	        if (!forma.parcelasValidas(parcelas)) {
50	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
51	        }
52	
53	        BigDecimal seguro = regiao.seguro(subtotal);
54	        BigDecimal totalPedido = Dinheiro.centavos(subtotal.subtract(desconto).add(frete).add(seguro));
55	        if (!forma.disponivel(totalPedido)) {
56	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
57	        }
58	
59	        FormaPagamento.Resultado pagamento = forma.calcular(totalPedido, parcelas);
60	        BigDecimal ajuste = Dinheiro.centavos(pagamento.valorFinal().subtract(totalPedido));
61	
62	        return new Resumo(
63	                subtotal,
64	                desconto,
65	                frete,
66	                modalidade.prazoDias(),
67	                seguro,
68	                ajuste,
69	                pagamento.valorFinal(),
70	                parcelas,
71	                pagamento.valorParcela(),
72	                nivel.credito(subtotal),
73	                nivel.brinde(subtotal));
74	    }
75	
76	    private List<ItemPedido> validarItens(List<ItemRequest> itens) {
77	        if (itens == null || itens.isEmpty()) {
78	            throw new CheckoutException("PEDIDO_INVALIDO");
79	        }
80	        List<ItemPedido> validados = new ArrayList<>();
81	        for (ItemRequest item : itens) {
82	            if (!positivo(item.precoUnitario()) || item.quantidade() == null || item.quantidade() <= 0
83	                    || !positivo(item.pesoKg())) {
84	                throw new CheckoutException("PEDIDO_INVALIDO");
85	            }
86	            validados.add(new ItemPedido(item.precoUnitario(), item.quantidade(), item.pesoKg()));
87	        }
88	        return validados;
89	    }
90	
91	    private BigDecimal resolverDesconto(String codigo, Cupom.Contexto contexto) {
92	        if (codigo == null) {
93	            return Dinheiro.centavos(BigDecimal.ZERO);
94	        }
95	        Cupom cupom = Cupom.resolver(codigo)
96	                .orElseThrow(() -> new CheckoutException("CUPOM_INVALIDO"));
97	        if (!cupom.aplicavel(contexto)) {
98	            throw new CheckoutException("CUPOM_NAO_APLICAVEL");
99	        }
100	        return cupom.desconto(contexto);
101	    }
102	
103	    private static boolean positivo(BigDecimal valor) {
104	        return valor != null && valor.compareTo(BigDecimal.ZERO) > 0;
105	    }
106	
107	    private static BigDecimal somar(List<BigDecimal> valores) {
108	        return valores.stream().reduce(BigDecimal.ZERO, BigDecimal::add);
109	    }
110	}
