19	        }
20	    },
21	    MENOS50 {
22	        @Override
23	        public boolean aplicavel(Contexto ctx) {
24	            return ctx.subtotalProdutos().compareTo(new BigDecimal("300")) >= 0;
25	        }
26	
27	        @Override
28	        public BigDecimal desconto(Contexto ctx) {
29	            return Dinheiro.centavos(new BigDecimal("50"));
30	        }
31	    },
32	    FRETEGRATIS {
33	        @Override
34	        public BigDecimal desconto(Contexto ctx) {
35	            return ctx.frete();
36	        }
37	    },
38	    LEVE3PAGUE2 {
