1	package com.loja.checkout.domain;
2	
3	import java.math.BigDecimal;
4	import java.util.Optional;
5	
6	/**
7	 * Forma de pagamento. Cada forma tem suas parcelas permitidas, sua
8	 * disponibilidade e seu ajuste sobre o total do pedido; cada uma mora no seu
9	 * próprio membro. O resultado traz valor final e valor da parcela, porque no
10	 * cartão com juros o valor final é parcela × nº de parcelas (≠ total), enquanto
11	 * nos demais casos o valor final é o próprio total ajustado.
12	 */
13	public enum FormaPagamento {
14	
15	    PIX {
16	        @Override
17	        public boolean parcelasValidas(int parcelas) {
18	            return parcelas == 1;
19	        }
20	
21	        @Override
22	        public Resultado calcular(BigDecimal totalPedido, int parcelas) {
23	            BigDecimal desconto = Dinheiro.centavos(totalPedido.multiply(new BigDecimal("0.05")));
24	            BigDecimal valorFinal = Dinheiro.centavos(totalPedido.subtract(desconto));
25	            return new Resultado(valorFinal, valorFinal);
26	        }
27	    },
28	    BOLETO {
29	        @Override
30	        public boolean parcelasValidas(int parcelas) {
31	            return parcelas == 1;
32	        }
33	
34	        @Override
35	        public boolean disponivel(BigDecimal totalPedido) {
36	            return totalPedido.compareTo(new BigDecimal("1000")) <= 0;
37	        }
38	
39	        @Override
40	        public Resultado calcular(BigDecimal totalPedido, int parcelas) {
41	            BigDecimal valorFinal = Dinheiro.centavos(totalPedido.add(new BigDecimal("3.49")));
42	            return new Resultado(valorFinal, valorFinal);
43	        }
44	    },
45	    CARTAO {
46	        private static final int SEM_JUROS_ATE = 3;
47	        private static final double TAXA_MENSAL = 0.0199;
48	
49	        @Override
50	        public boolean parcelasValidas(int parcelas) {
51	            return parcelas >= 1 && parcelas <= 12;
52	        }
53	
54	        @Override
55	        public Resultado calcular(BigDecimal totalPedido, int parcelas) {
56	            if (parcelas <= SEM_JUROS_ATE) {
57	                BigDecimal parcela = Dinheiro.centavos(
58	                        totalPedido.divide(BigDecimal.valueOf(parcelas), 10, java.math.RoundingMode.HALF_EVEN));
59	                return new Resultado(Dinheiro.centavos(totalPedido), parcela);
60	            }
61	            double fator = 1 - Math.pow(1 + TAXA_MENSAL, -parcelas);
62	            double parcelaBruta = totalPedido.doubleValue() * TAXA_MENSAL / fator;
63	            BigDecimal parcela = Dinheiro.centavos(BigDecimal.valueOf(parcelaBruta));
64	            BigDecimal valorFinal = Dinheiro.centavos(parcela.multiply(BigDecimal.valueOf(parcelas)));
65	            return new Resultado(valorFinal, parcela);
66	        }
67	    };
68	
69	    public abstract boolean parcelasValidas(int parcelas);
70	
71	    public boolean disponivel(BigDecimal totalPedido) {
72	        return true;
73	    }
74	
75	    public abstract Resultado calcular(BigDecimal totalPedido, int parcelas);
76	
77	    public static Optional<FormaPagamento> resolver(String codigo) {
78	        return Catalogo.achar(FormaPagamento.class, codigo);
79	    }
80	
81	    public record Resultado(BigDecimal valorFinal, BigDecimal valorParcela) {
82	    }
83	}
